package org.agentfrc.lesson;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
class PoweredGuideTest {
 @org.junit.jupiter.api.AfterAll static void binding() throws Exception {
  String token=System.getenv("FRC_POWERED_RUN_ID"),output=System.getenv("FRC_POWERED_RUNTIME");if(token==null&&output==null)return;assertNotNull(token);assertNotNull(output);
  var p=new java.util.Properties();p.setProperty("runId",token);
  for(Class<?> c:new Class<?>[]{PoweredGuidePlant.class,PoweredGuidePlant.Config.class,PoweredGuidePlant.Sample.class,PoweredGuideTest.class,SharedSupply.class,SharedSupply.Result.class,edu.wpi.first.math.system.plant.DCMotor.class}){String n=c.getName().substring(c.getName().lastIndexOf('.')+1);p.setProperty(n+"Sha256",java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(c.getResourceAsStream(n+".class").readAllBytes())));}
  try(var stream=java.nio.file.Files.newOutputStream(java.nio.file.Path.of(output),java.nio.file.StandardOpenOption.CREATE_NEW)){p.store(stream,"Fresh powered guide execution");}System.out.println("POWERED_RUN_ID="+token);
 }
 static PoweredGuidePlant.Config config(int year,double normal,double supply){return new PoweredGuidePlant.Config(year==2024?.235:year==2025?.65:.215,year==2024?.0508:year==2025?.0254:.0381,.004,year==2025?.15:.3,year==2024?Math.toRadians(50):year==2025?0:Math.toRadians(60),normal,.8,year==2025?.08:.6,supply);}
 static PoweredGuidePlant.Sample run(int y,double dt,double normal,double volts){var p=new PoweredGuidePlant(config(y,normal,volts));for(int k=0;k<Math.round(2/dt);k++)p.step(dt);p.feed(.2);var r=p.sample();for(int k=0;k<Math.round(3/dt)&&!r.exited();k++){r=p.step(dt);assertEquals(0,r.energyResidual(),2e-5);}return r;}
 @Test void poweredExitsAndTimestepSensitivity(){for(int y:new int[]{2024,2025,2026})for(double volts:new double[]{9,12}){var a=run(y,.0001,15,volts);var b=run(y,.00005,15,volts);assertTrue(a.exited());assertTrue(b.exited());assertEquals(config(y,15,volts).length(),a.x(),1e-12);assertEquals(a.speed(),b.speed(),.0001);assertEquals(a.time(),b.time(),.00001);assertTrue(a.motorWork()>a.feedEnergy());System.out.println("POWERED_EXIT year="+y+" volts="+volts+" dt="+.00005+" angleRad="+config(y,15,volts).angle()+" massKg="+config(y,15,volts).mass()+" guideLengthM="+config(y,15,volts).length()+" radiusM="+config(y,15,volts).radius()+" inertiaEach="+config(y,15,volts).inertiaEach()+" "+b);}}
 @Test void horizontalUnpoweredRollersCannotCreateEnergy(){var p=new PoweredGuidePlant(new PoweredGuidePlant.Config(.65,.0254,.004,.15,0,15,.8,0,12));p.feed(.2);for(int k=0;k<10000;k++){var s=p.step(.0001);assertTrue(s.motorWork()<=1e-12);assertTrue(s.frictionLoss()>=0);assertEquals(0,s.energyResidual(),1e-8);assertTrue(s.speed()<=.2);}}
 @Test void noContactDoesNotPropelHorizontalPiece(){var p=new PoweredGuidePlant(config(2025,0,12));for(int k=0;k<20000;k++)p.step(.0001);p.feed(0);for(int k=0;k<10000;k++)p.step(.0001);assertEquals(0,p.sample().x());assertFalse(p.sample().exited());assertEquals(0,p.sample().frictionLoss());}
 @Test void reducedNormalForceReducesExitEnergy(){for(int y:new int[]{2024,2026}){var low=run(y,.0001,5,12);var high=run(y,.0001,15,12);assertTrue(low.exited());assertTrue(low.speed()<high.speed());}}
 @Test void invalidAndRepeatedFeedRejected(){assertThrows(IllegalArgumentException.class,()->config(2024,Double.NaN,12));var p=new PoweredGuidePlant(config(2024,15,12));assertThrows(IllegalArgumentException.class,()->p.step(Double.NaN));p.feed(.2);assertThrows(IllegalArgumentException.class,()->p.feed(.2));}
}
